/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  --ink: #202b32;
  --ink-soft: #46545b;
  --navy: #263b49;
  --navy-deep: #192c38;
  --accent: #bd783f;
  --accent-dark: #995a2c;
  --paper: #f8f7f3;
  --white: #ffffff;
  --sand: #eae5dc;
  --line: #dcd9d1;
  --muted: #747d7e;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Arial, sans-serif;

  --container: 1180px;
  --gutter: 40px;
  --radius: 3px;
  --shadow: 0 14px 40px rgba(25, 44, 56, 0.12);

  --transition: 180ms ease;
}

/* RESET */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

::selection {
  background: var(--accent);
  color: var(--white);
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(3.2rem, 6vw, 5.7rem);
}

h2 {
  margin-bottom: 22px;
  font-size: clamp(2.35rem, 4vw, 3.6rem);
}

h3 {
  font-size: 1.65rem;
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--accent-dark);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.17em;
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 27px;
  height: 2px;
  background: var(--accent);
  content: "";
}

.section-heading {
  max-width: 720px;
  margin-bottom: 48px;
}

.section-heading p {
  max-width: 600px;
  margin-bottom: 0;
  font-size: 1.08rem;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--accent-dark);
  font-weight: 750;
  transition: gap var(--transition);
}

.text-link:hover {
  gap: 15px;
}

/* PAGE STRUCTURE */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding: 108px 0;
}

.section--light {
  background: var(--white);
}

.section--dark {
  background: var(--navy-deep);
  color: var(--white);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark p {
  color: #d0d7d8;
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 43, 50, 0.09);
}

.header-inner {
  display: flex;
  min-height: 94px;
  align-items: center;
  justify-content: space-between;
  gap: 36px;
}

.brand {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 14px;
}

.brand-logo {
  width: 76px;
  height: 70px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-name {
  color: var(--navy-deep);
  font-family: var(--font-display);
  font-size: 1.12rem;
  font-weight: 700;
  line-height: 1.15;
}

.brand-caption {
  color: var(--muted);
  font-size: 0.64rem;
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 30px;
}

.primary-nav a:not(.button) {
  color: var(--ink-soft);
  font-size: 0.84rem;
  font-weight: 700;
  transition: color var(--transition);
}

.primary-nav a:not(.button):hover {
  color: var(--accent-dark);
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--accent);
  color: var(--white);
  font-size: 0.86rem;
  font-weight: 800;
  letter-spacing: 0.025em;
  line-height: 1.3;
  text-align: center;
  cursor: pointer;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
  background: var(--accent-dark);
}

.button--dark {
  background: var(--navy-deep);
}

.button--dark:hover {
  background: var(--navy);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--navy-deep);
}

.button--light {
  border-color: var(--line);
  background: var(--white);
  color: var(--navy-deep);
}

.button--light:hover {
  border-color: var(--accent);
  background: var(--paper);
}

/* HERO */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--navy-deep);
  color: var(--white);
}

.hero-inner {
  display: grid;
  min-height: 650px;
  grid-template-columns: 1fr 0.92fr;
  align-items: stretch;
}

.hero-content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: 85px 60px 90px max(40px, calc((100vw - var(--container)) / 2));
}

.hero .eyebrow {
  color: #e7b27e;
}

.hero h1 {
  max-width: 670px;
  margin-bottom: 25px;
  color: var(--white);
}

.hero-description {
  max-width: 520px;
  margin-bottom: 32px;
  color: #d5dcde;
  font-size: 1.08rem;
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  margin-top: 30px;
  color: #c3cdcf;
  font-size: 0.83rem;
}

.hero-media {
  position: relative;
  min-height: 650px;
  overflow: hidden;
}

.hero-media::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(25, 44, 56, 0.2),
    transparent 35%,
    rgba(25, 44, 56, 0.08)
  );
  content: "";
  pointer-events: none;
}

.hero-media img {
  width: 100%;
  height: 100%;
  min-height: 650px;
  object-fit: cover;
  object-position: center;
}

/* TRUST / COMPANY INTRODUCTION */
.intro-section {
  padding: 76px 0;
  border-bottom: 1px solid var(--line);
  background: var(--white);
}

.intro-inner {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  align-items: center;
  gap: 75px;
}

.intro-stat {
  padding-right: 45px;
  border-right: 1px solid var(--line);
}

.intro-stat strong {
  display: block;
  color: var(--accent-dark);
  font-family: var(--font-display);
  font-size: 4.5rem;
  font-weight: 400;
  line-height: 1;
}

.intro-stat span {
  display: block;
  margin-top: 12px;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.intro-copy h2 {
  margin-bottom: 15px;
  font-size: 2.2rem;
}

.intro-copy p {
  max-width: 670px;
  margin-bottom: 0;
}

/* WHY CHOOSE US */
.why-section {
  background: var(--paper);
}

.why-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: start;
  gap: 90px;
}

.why-intro {
  position: sticky;
  top: 35px;
}

.why-intro p {
  max-width: 440px;
  font-size: 1.05rem;
}

.why-points {
  border-top: 1px solid var(--line);
}

.why-point {
  display: grid;
  grid-template-columns: 55px 1fr;
  gap: 22px;
  padding: 29px 0;
  border-bottom: 1px solid var(--line);
}

.why-number {
  color: var(--accent-dark);
  font-family: var(--font-display);
  font-size: 1.6rem;
}

.why-point h3 {
  margin-bottom: 8px;
  font-size: 1.5rem;
}

.why-point p {
  max-width: 520px;
  margin-bottom: 0;
  font-size: 0.94rem;
}

/* ROOFING / RESTORATION */
.roof-section {
  background: var(--navy);
  color: var(--white);
}

.roof-section .section-heading h2 {
  color: var(--white);
}

.roof-section .section-heading p {
  color: #d1dadd;
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 75px;
}

.roof-media {
  position: relative;
  min-height: 510px;
  overflow: hidden;
  background: #344a57;
}

.roof-media img {
  width: 100%;
  height: 510px;
  object-fit: cover;
  object-position: center;
}

.roof-content h3 {
  margin-bottom: 20px;
  color: var(--white);
  font-size: 2rem;
}

.roof-content > p {
  color: #d1dadd;
}

.roof-signs {
  margin: 30px 0;
  padding: 0;
  list-style: none;
}

.roof-signs li {
  position: relative;
  padding: 13px 0 13px 29px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  color: #edf0ef;
}

.roof-signs li::before {
  position: absolute;
  top: 22px;
  left: 2px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #e7b27e;
  content: "";
}

/* COLORADO ROOFING GUIDE */
.guide-section {
  background: var(--white);
}

.guide-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 90px;
}

.guide-intro {
  position: sticky;
  top: 35px;
}

.guide-intro p {
  max-width: 430px;
}

.guide-steps {
  counter-reset: guide-step;
  border-top: 1px solid var(--line);
}

.guide-step {
  position: relative;
  padding: 29px 0 29px 75px;
  border-bottom: 1px solid var(--line);
  counter-increment: guide-step;
}

.guide-step::before {
  position: absolute;
  top: 27px;
  left: 0;
  color: var(--accent-dark);
  font-family: var(--font-display);
  font-size: 2rem;
  content: counter(guide-step, decimal-leading-zero);
}

.guide-step h3 {
  margin-bottom: 9px;
  font-size: 1.5rem;
}

.guide-step p {
  margin-bottom: 0;
  font-size: 0.94rem;
}

/* RECENT PROJECTS */
.projects-section {
  background: var(--paper);
}

.projects-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
}

.projects-heading .section-heading {
  margin-bottom: 48px;
}

.project-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 30px;
}

.project {
  min-width: 0;
}

.project--featured {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  align-items: stretch;
  background: var(--white);
}

.project-media {
  position: relative;
  min-height: 340px;
  overflow: hidden;
  background: var(--sand);
}

.project-media img {
  width: 100%;
  height: 100%;
  min-height: 340px;
  object-fit: cover;
  transition: transform 450ms ease;
}

.project:hover .project-media img {
  transform: scale(1.035);
}

.project-info {
  padding: 28px 30px;
}

.project--featured .project-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 45px;
}

.project-category {
  display: block;
  margin-bottom: 12px;
  color: var(--accent-dark);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.project-info h3 {
  margin-bottom: 10px;
  font-size: 1.7rem;
}

.project-info p {
  margin-bottom: 0;
  font-size: 0.91rem;
}

/* MOTION ACCESSIBILITY */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
