/* CSS PART 2 OF 2 */

/* CONTACT / CONVERSION */
.contact-section {
  padding: 110px 0;
  background: var(--navy-deep);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 85px;
}

.contact-copy h2 {
  color: var(--white);
}

.contact-copy > p {
  max-width: 440px;
  color: #d0d7d8;
}

.contact-details {
  display: flex;
  flex-direction: column;
  gap: 17px;
  margin-top: 38px;
}

.contact-details a {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: var(--white);
  font-weight: 750;
  overflow-wrap: anywhere;
}

.contact-details a:hover {
  color: #e7b27e;
}

.contact-form {
  padding: 42px;
  background: var(--white);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.contact-form h3 {
  margin-bottom: 10px;
  font-size: 2rem;
}

.contact-form > p {
  margin-bottom: 28px;
  font-size: 0.91rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 19px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: 0.81rem;
  font-weight: 750;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 49px;
  padding: 12px 14px;
  border: 1px solid #c9cbc6;
  border-radius: var(--radius);
  background: #fcfcfa;
  color: var(--ink);
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858c8c;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--accent-dark);
  outline: 2px solid rgba(189, 120, 63, 0.2);
  outline-offset: 1px;
}

.form-submit {
  width: 100%;
  margin-top: 24px;
}

.form-note {
  margin: 14px 0 0;
  color: var(--muted);
  font-size: 0.76rem;
  text-align: center;
}

/* FOOTER */
.site-footer {
  padding: 45px 0 25px;
  background: #142530;
  color: #d0d7d8;
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-bottom: 35px;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 15px;
}

.footer-brand img {
  width: 65px;
  height: 60px;
  object-fit: contain;
}

.footer-brand strong {
  display: block;
  color: var(--white);
  font-family: var(--font-display);
  font-size: 1.1rem;
}

.footer-brand span {
  display: block;
  color: #aebabc;
  font-size: 0.72rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 22px;
}

.footer-links a {
  color: #d0d7d8;
  font-size: 0.82rem;
  font-weight: 650;
}

.footer-links a:hover {
  color: #e7b27e;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  color: #aebabc;
  font-size: 0.75rem;
}

/* MOBILE NAVIGATION CONTROL */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--white);
  color: var(--navy-deep);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* TABLET */
@media (max-width: 1050px) {
  :root {
    --gutter: 30px;
  }

  .primary-nav {
    gap: 17px;
  }

  .header-inner {
    gap: 20px;
  }

  .hero-inner {
    grid-template-columns: 1fr 0.8fr;
  }

  .hero-content {
    padding-right: 35px;
  }

  .why-layout,
  .guide-layout {
    gap: 50px;
  }

  .roof-layout,
  .contact-layout {
    gap: 45px;
  }

  .intro-inner {
    gap: 45px;
  }

  .project--featured .project-info {
    padding: 30px;
  }
}

/* MOBILE AND NARROW TABLET */
@media (max-width: 760px) {
  :root {
    --gutter: 22px;
  }

  html {
    scroll-padding-top: 75px;
  }

  body {
    font-size: 15px;
  }

  .section {
    padding: 75px 0;
  }

  .header-inner {
    position: relative;
    min-height: 76px;
    gap: 12px;
  }

  .brand {
    min-width: 0;
    gap: 9px;
  }

  .brand-logo {
    width: 55px;
    height: 53px;
  }

  .brand-name {
    font-size: 0.94rem;
  }

  .brand-caption {
    font-size: 0.55rem;
  }

  .menu-toggle {
    display: flex;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: calc(100% + 1px);
    left: calc(-1 * var(--gutter));
    right: calc(-1 * var(--gutter));
    z-index: 30;
    max-height: calc(100vh - 90px);
    overflow-y: auto;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0;
    padding: 12px var(--gutter) 22px;
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    background: var(--white);
    box-shadow: 0 12px 20px rgba(25, 44, 56, 0.12);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    display: block;
    padding: 13px 0;
    border-bottom: 1px solid var(--line);
  }

  .primary-nav .button {
    width: 100%;
    margin-top: 16px;
  }

  h1 {
    font-size: clamp(2.9rem, 12vw, 4.4rem);
  }

  h2 {
    font-size: clamp(2.2rem, 9vw, 3rem);
  }

  .section-heading {
    margin-bottom: 34px;
  }

  .hero-inner {
    display: flex;
    flex-direction: column;
  }

  .hero-content {
    padding: 76px var(--gutter) 55px;
  }

  .hero h1 {
    max-width: 600px;
  }

  .hero-description {
    font-size: 1rem;
  }

  .hero-media {
    min-height: 340px;
    height: 340px;
  }

  .hero-media img {
    min-height: 340px;
  }

  .hero-actions {
    align-items: stretch;
    width: 100%;
  }

  .hero-actions .button {
    width: 100%;
  }

  .intro-section {
    padding: 55px 0;
  }

  .intro-inner {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .intro-stat {
    padding: 0 0 25px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .intro-stat strong {
    font-size: 3.6rem;
  }

  .intro-copy h2 {
    font-size: 2rem;
  }

  .why-layout,
  .guide-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .why-intro,
  .guide-intro {
    position: static;
  }

  .why-point {
    grid-template-columns: 42px 1fr;
    gap: 14px;
    padding: 24px 0;
  }

  .roof-layout {
    grid-template-columns: 1fr;
    gap: 30px;
  }

